/// <summary>
/// CB392_CustomerOperationsGroup
/// Script to fix data in GUPPricingAttributeLink after renaming METGUPPricingAttributeMETCustTableCustOprGrp to METGUPPricingAttributeCustTableCustOprGrp
/// and moving CustOperGroupId from METCustTable into CustTable.METCustOperGroupId
/// </summary>
internal final class METFixGUPPricingAttributeLinkCustOperGroupId
{
}

Method.Source:
    /// <summary>
    /// Class entry point. The system will call this method when a designated menu 
    /// is selected or when execution starts and this class is set as the startup class.
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>
    public static void main(Args _args)
    {
        GUPPricingAttributeLink GUPPricingAttributeLink;
        ClassId classId = classNum(METGUPPricingAttributeCustTableCustOprGrp);
        ttsbegin;
        GUPPricingAttributeLink.skipDataMethods(true);
        update_recordset GUPPricingAttributeLink
            setting PriceAttributeClassId = classId, 
                    SourceName = 'CustTable', 
                    FieldName = 'METCustOperGroupId', 
                    TableName = 'CustTable',
                    FieldPath = 'SalesTable#CustTable_CustAccount$AccountNum#METCustOperGroupId'
            where GUPPricingAttributeLink.SourceName == 'METCustTable' && GUPPricingAttributeLink.FieldName == 'CustOperGroupId';
        ttscommit;

        info("Update completed");
    }
